static struct l9p_acl * l9p_sysacl_to_acl ( int acetype , acl_t sysacl , econvertfn * convert ) { struct l9p_acl * acl ; acl_entry_t entry ; uint32_t n ; int error , id ; acl = l9p_new_acl ( ( uint32_t ) acetype , ( uint32_t ) l9p_count_aces ( sysacl ) ) ; id = ACL_FIRST_ENTRY ; for ( n = 0 ; ; ) { if ( acl_get_entry ( sysacl , id , & entry ) != 1 ) { break ; } acl = l9p_growacl ( acl , n + 1 ) ; if ( acl == NULL ) { return ( NULL ) ; } error = * convert ( entry , & acl -> acl_aces [ n ] ) ; id = ACL_NEXT_ENTRY ; if ( error == 0 ) { n ++ ; } } acl -> acl_nace = n ; return ( acl ) ; } 